// BIFURCA 検索インデックス — 作品・辞典・ログを追加する場合はここを編集
const INDEX = [{"type": "辞典", "title": "赤土の約束", "subtitle": "（あかつちのやくそく）　名詞・民話・カルナ人", "body": "入植者の長と先住の民の長が結んだ土地分割の約束が、世代を経て一方的に破られる物語。「嵐の夜に赤土の道を歩く足音」という慣用句で語られるが、その正体を子供に説明する語彙が文化的に発達していない。", "url": "dict/akatsuchi.html"}, {"type": "辞典", "title": "ビフルカ", "subtitle": "（びふるか）　固有名詞・世界名称", "body": "この世界の外部名称（学術・外交的文脈で使われる中立的呼称）。「bifurcation」のラテン語語源「bi-（二つ）＋furca（叉、枝分かれ）」に由来し、「二つに分岐した」を意味する。ただし「分岐」の語源は「かつて一つだった幹からの枝分かれ」を含意しており「分断」（断絶）とは異なる。iiHRQY9Ktが候補として提示し、スレッド参加者の合意のもとに決定した。", "url": "dict/bifurca-entry.html"}, {"type": "辞典", "title": "膝を折らなかった牧者", "subtitle": "（ひざをおらなかったぼくしゃ）　名詞・民話・コルダ人", "body": "家畜競争に負け続けた牧者が、最後の競争で空の手綱だけを持って立ち、敗北しながらも英雄として記憶される物語。子孫は「空の手綱の家系」と呼ばれ、最も名誉ある家名の一つとなっている。", "url": "dict/bokusya.html"}, {"type": "辞典", "title": "骨の割符", "subtitle": "（ほねのわりふ）　名詞・経済制度・サハール人", "body": "サハール人の負債記録システム。家畜の骨を割り、貸し手と借り手がそれぞれ半分を保有する。双方が揃わないと負債関係が証明できない。骨の割符の交換行為自体が神への誓いを立てる儀礼を兼ねていたとされる。東洋通貨への切り替えで骨の割符の意味が消えた出来事は、単なる経済的暴力ではなく宗教的な冒涜でもあった。", "url": "dict/bone-warifu.html"}, {"type": "辞典", "title": "分岐点の証人", "subtitle": "（ぶんきてんのしょうにん）　名詞・物語論・民俗学", "body": "ンガ・ソルの出現条件を説明する概念。本人が移動しているのではなく、誰かが重大な決断の岐路に立ち、その重さそのものが存在を引き寄せるとされる。「もし違う選択をしていたら歴史が変わった」瞬間に必ずそこにいる。", "url": "dict/bunkiten-shonin.html"}, {"type": "辞典", "title": "文明論的言説", "subtitle": "（ぶんめいろんてきげんせつ）　名詞・社会学・植民地主義", "body": "東洋帝国が西大陸の植民地化を正当化するために生産した言説の総体。約120万語の植民地期コーパス分析において「単純」「感情的」「部族的」「資源を活用できない」という語彙が繰り返し生産されていたことが確認された。地理的・歴史的な条件によって生まれた格差を「内在的な能力・文化の欠如」として再記述し、収奪を善意の言葉で包む。", "url": "dict/bunmeiran-gensetsu.html"}, {"type": "辞典", "title": "ビザンチン将軍問題", "subtitle": "（びざんちんしょうぐんもんだい）　名詞・計算機科学・政治学", "body": "複数の独立した主体が、裏切り者の混在する状況下でどうやって全員が同じ行動に合意できるかという問題。サハール人の氏族連合が東洋帝国の分断工作（特定の氏族への貿易特権付与）によって崩壊するプロセスを、「将軍の一人を裏切り者に変えることで全体の合意形成を不可能にする攻撃」として定式化した。", "url": "dict/byzantine.html"}, {"type": "辞典", "title": "誓いの環", "subtitle": "（ちかいのわ）　名詞・聖典・サハール人", "body": "サハール人の聖典。循環的に詠唱される氏族間の誓約の総体で、慣習法と半分重なっている。東洋通貨への切り替えで骨の割符の意味が消えた出来事は、単なる経済的暴力ではなく「神への誓いの強制的な無効化」でもあった。", "url": "dict/chikai-no-wa.html"}, {"type": "辞典", "title": "地域別呼称", "subtitle": "（ちいきべつこしょう）　名詞・民俗学・ンガ・ソル", "body": "ンガ・ソルが東西各民族の言語においてそれぞれ異なる名称を持つことを指す。統一名称「ンガ・ソル（二重の影）」はリンガ語による呼び名であり、他の民族はそれぞれ独自の言語で異なる名で呼んでいる。後の比較言語学的研究によって同一の存在を指すモチーフであることが指摘された。", "url": "dict/chiki-betsushosho.html"}, {"type": "辞典", "title": "長夜会", "subtitle": "（ちょうやかい）　名詞・祭礼・ヴェルカ人", "body": "ヴェルカ人の冬至の祭礼。複数の語り手がそれぞれ違う宇宙論を同じ夜に語り、矛盾はそのまま受け入れられる。一つの夜に複数の創世神話が並立して語られても誰も異端と呼ばない。", "url": "dict/choya-kai.html"}, {"type": "辞典", "title": "ダル・カディム", "subtitle": "（だるかでぃむ）　固有名詞・世界固有名称・サハール人", "body": "サハール人が自分たちの世界をどう呼ぶかを示す固有名称。「審判の庭」を意味する。「ダル」が庭・場所・家、「カディム」が審判・裁き・試練を意味し、この世界は神が魂を試す場所であり、生は試練の旅だという世界観を表す。氏族の誓いを立てる際に「ダル・カディムの前で誓う」という表現が使われる。", "url": "dict/dar-kadim.html"}, {"type": "辞典", "title": "ダル・サーリム", "subtitle": "（だるさーりむ）　固有名詞・主要都市・サハール人", "body": "サハール人の旗艦都市。サハール語で「誓いの家」。赤道西洋大陸中央部、三つの砂漠地帯の境界点に位置する。三方向からの隊商路が集まり、地下帯水層が都市の水源を支える。地下水・隊商路・誓約ネットワークの三要素が都市を成立させた。象徴は「壁都市」の構造。三重の外壁が都市を囲み、各壁には隊商の誓いが刻まれている。内壁に刻まれた誓いほど古く権威が高い。中心の「誓司の塔」には骨の割符の原本が保管されており、ここ", "url": "dict/dar-sarim.html"}, {"type": "辞典", "title": "動的グラフ", "subtitle": "（どうてきぐらふ）　名詞・計算機科学", "body": "ノードやエッジが時刻によって存在したり消えたりするネットワーク構造。「テンポラルグラフ」とも呼ばれる。峠帯が季節によって通行可能・不可能と変動することを、静的グラフではなく動的グラフとして再定義したのはdeQkh5fh（気候科学者）。この視点によりリンガ人の独占力が季節によって変動するという設定が追加された。", "url": "dict/douteki-graph.html"}, {"type": "辞典", "title": "東大陸群", "subtitle": "（ひがしたいりくぐん）　固有名詞・地理", "body": "グランドリッジの東側に位置する大陸群の総称。暖流・大河・豊富な石炭と鉄資源・農業適地が集中し、文明の先行発展を可能にした。ノルド東洋大陸・赤道東洋大陸・南東洋大陸の三大陸から構成される。", "url": "dict/east-continents.html"}, {"type": "辞典", "title": "疫病の上方歪曲", "subtitle": "（えきびょうのじょうほうわいきょく）　名詞・失政パターン・ヴァルン帝国", "body": "ヴァルン帝国の官僚制における疫病報告の構造的歪み。辺境の地方官僚が疫病の発生を中央に正確に報告すれば自分の管理能力不足として処罰される可能性があるため、「軽微な季節病」として過小に報告し続けた現象。「情報の上方歪曲」という失政パターンの、疫学的な具体例。サハーラ病の本当の規模と頻度が、帝国中央には長期間正確に伝わらなかった。", "url": "dict/ekibyo-uwakuwaku.html"}, {"type": "辞典", "title": "不臥の宴", "subtitle": "（ふがのうたげ）　名詞・祭礼・コルダ人", "body": "コルダ人の出陣前夜の儀礼。夜通し戦死者を讃えて眠らずに過ごす。「屈服しない」という宗教的態度を儀礼として体に刻み込む機能を持つ。", "url": "dict/fuga-no-utage.html"}, {"type": "辞典", "title": "二つの名を持つ峠", "subtitle": "（ふたつのなをもつとうげ）　名詞・民話・リンガ人", "body": "東西それぞれの旅人に異なる名を答えていた案内人が、両者から同時に問われた際「峠は答えを持っていない」と返す物語。語られる言語によって案内人の評価（知恵者／無責任な者）が変わる。後の研究でンガ・ソルの記録の一つではないかとする説が提起された。", "url": "dict/futatsuno-toge.html"}, {"type": "辞典", "title": "原宗教（仮説）", "subtitle": "（げんしゅきょう）　名詞・宗教学・未確認事象", "body": "古西語の発見と並行して提起された仮説。西大陸六民族の六つの宗教体系（天の官僚制・個人契約の守り神・森の精霊・契約の壁・英雄神族・山そのものへの耳澄まし）が、かつて単一の「原宗教」から分岐した可能性を指す。古西語の三百語の中に「神」に相当する語があるとすれば、その指す対象は現在のどの神とも一致しない。「古西語の発見が西大陸連帯の起点になる」という設定の、宗教的な完成形として位置づけられる。", "url": "dict/gen-shukyo.html"}, {"type": "辞典", "title": "グランドリッジ", "subtitle": "（ぐらんどりっじ）　固有名詞・地理／地質", "body": "北極点から南極点まで連続して走る超山脈。平均標高6,500m、最高峰9,200m級、最大幅500km。東西両大陸を完全に遮断する惑星規模の地形的障壁。プレートテクトニクスの特殊な配置（南北方向に移動する二つの巨大プレートが東西方向の境界で衝突し続けること）によって形成された。偏西風を完全にブロックするため、東西の大気循環は独立している。", "url": "dict/grand-ridge.html"}, {"type": "辞典", "title": "灰道祭", "subtitle": "（はいみちさい）　名詞・祭礼・カルナ人", "body": "カルナ人の祭礼。表向きは収穫祭・先祖供養とされるが、夕暮れに赤土の道へ目印の灯りを置いて歩くという作法だけが由来不明のまま継承されている。先住の民の葬送儀礼における「先導霊」の概念が変質した可能性が考古学的調査で示唆されている。", "url": "dict/hai-michi-sai.html"}, {"type": "辞典", "title": "初波", "subtitle": "（はつなみ）　名詞・祭礼・タラッサ人", "body": "タラッサ人の新造船進水前に行う祝福儀礼。寄進の額がそのまま儀式の規模を決める。「信仰の市場価格がそのまま見える稀有な祭礼」（tkri7cDV）。", "url": "dict/hatsunami.html"}, {"type": "辞典", "title": "秘密分散法", "subtitle": "（ひみつさんさんほう）　名詞・計算機科学・リンガ人制度", "body": "一つの秘密情報を複数の断片に分割し、ある決まった数以上の断片を集めないと元の情報を復元できないようにする暗号理論の技術。リンガ人の峠管理体制に応用——「七つの峠管理家系のうち、最低でも四家系が協力しないと全体図は完成しない」という設計。一家系が裏切っても情報の全体は漏れない。", "url": "dict/himitsu-sansan.html"}, {"type": "辞典", "title": "賓客の大角", "subtitle": "（ひんきゃくのだいかく）　名詞・料理・コルダ人", "body": "家畜の中で最も角の立派な一頭を丸ごと使う最高級のもてなし料理。一度この料理で客をもてなすと、その後どんな不利な条件でも相手を「対等な関係」として扱う作法上の義務が生じる。", "url": "dict/hinkyaku.html"}, {"type": "辞典", "title": "祠守", "subtitle": "（ほこらもり）　名詞・聖職者称号・タラッサ人", "body": "タラッサ人において聖職者に最も近い役割。引退した船乗りが片手間で担う非専業の仕事。統一された教義も組織もなく、「公共財への過小投資」が宗教施設にもそのまま現れる。", "url": "dict/hokora-mori.html"}, {"type": "辞典", "title": "誉れ歌", "subtitle": "（ほまれうた）　名詞・聖典・コルダ人", "body": "コルダ人の英雄叙事詩の総称。内容は都市ごとに矛盾するため、統一された聖典は存在しない。各都市の英雄神を一つの神殿に並べて祀ることが「信仰上の妥協」にあたるため、政治的統一の前に宗教的統一が必要だが、それが最も困難な構造になっている。", "url": "dict/homare-uta.html"}, {"type": "辞典", "title": "本土経", "subtitle": "（ほんどきょう）　名詞・聖典・カルナ人", "body": "カルナ人が使用する聖典。本土（東洋）から輸入された歳簿経の簡略版で、「輸入品であることが名前に刻まれている」とされる。輸入品としての聖典という構造が、宗教的植民地化のメカニズムを象徴する。", "url": "dict/hondo-kyo.html"}, {"type": "辞典", "title": "意図と責任の分離", "subtitle": "（いととせきにんのぶんり）　名詞・倫理学・道徳論", "body": "Ks5vTmHqが提示した植民地期の疫病伝播の道徳的評価の枠組み。「疫病の伝播そのものに最初の意図的な悪意はなかった」が、「人口減少に気づいた後もその弱みを利用し続けた選択には明確な責任がある」というもの。最初の引き金と、その後の継続的な利用を分けて評価することで、単純な悪役論にも単純な無罪論にも陥らない設計を可能にする。", "url": "dict/ito-sekinin.html"}, {"type": "辞典", "title": "情報寡頭制", "subtitle": "（じょうほうかとうせい）　名詞・政治経済・リンガ人", "body": "リンガ人が峠帯の情報（位置・通行可能時期・安全な季節）を独占することで東西間の情報流通を支配する政治経済的な構造。現代のプラットフォーム企業によるゲートキーパー独占と構造的に同型とされる。秘密分散法とリンガ語の戦略的あいまい性が、この独占を二重に保護している。", "url": "dict/joho-kadotsu.html"}, {"type": "辞典", "title": "情報の上方歪曲", "subtitle": "（じょうほうのじょうほうわいきょく）　名詞・政治学・失政パターン", "body": "ヴァルン帝国の官僚制が抱える構造的失政。下位から上位に情報が伝達される過程で、不都合な情報が意図的または無意識的に改ざん・隠蔽される現象。分散システム論の言葉では「整合性（コンシステンシー）の崩壊」として記述される。", "url": "dict/jouhou-uwakuwaku.html"}, {"type": "辞典", "title": "壁向きの夜", "subtitle": "（かべむきのよる）　名詞・祭礼・サハール人", "body": "サハール人の埋葬儀礼。遺骸をグランドリッジへ向けて安置し、同時に氏族の誓いを星空の下で更新する。誓いを破った者の魂は「壁（グランドリッジ）に近づけず、永遠に砂漠を歩く」という死生観と対をなす。", "url": "dict/kabe-muki-no-yoru.html"}, {"type": "辞典", "title": "冬を越えなかった会議", "subtitle": "（ふゆをこえなかったかいぎ）　名詞・民話・ヴェルカ人", "body": "冬支度の分担を決める動物たちの会議が、全員一致を待つあまり結論を出せないまま雪に埋もれる物語。「正典のない物語」であり、同一遺跡から異なる結末を刻んだ石板が複数出土している。", "url": "dict/kaigi.html"}, {"type": "辞典", "title": "格差の永続メカニズム", "subtitle": "（かくさのえいぞくめかにずむ）　名詞・経済学・tkri7cDV 第三論文", "body": "tkri7cDVの第三論文の主題。東西格差が縮まらない構造的理由の証明。「開放性トラップ」（東洋市場への開放が短期的利益をもたらすが長期的に自立的発展を阻む）が核心。唯一の脱出経路として「条件A（東洋内部改革）」または「条件B（西大陸連帯）」の二択を提示した。", "url": "dict/kakusa-eizoku.html"}, {"type": "辞典", "title": "観測の掟", "subtitle": "（かんそくのおきて）　名詞・伝承・規範", "body": "ンガ・ソルに帯びるとされる制約。「語ることはできるが、選ぶことはできない」という一文に要約される。リンガ語の戦略的あいまい性と同型の言語的制約が課されているとされる。", "url": "dict/kansoku-okite.html"}, {"type": "辞典", "title": "カルナ人", "subtitle": "（かるなじん）　固有名詞・民族", "body": "南東洋大陸の入植者の子孫。東洋海洋帝国による植民地化の過程で形成された、入植者と被植民地者の複合的なアイデンティティを持つ民族。先住の民との約束が世代を経て破られた歴史を抱え、先住民問題の時限爆弾という失政パターンを持つ。", "url": "dict/karna.html"}, {"type": "辞典", "title": "カルタ・エナ", "subtitle": "（かるたえな）　固有名詞・主要都市・カルナ人", "body": "カルナ人の旗艦都市。意味は「混ざった土地」。南東洋大陸の北西岸、グランドリッジの南端に最も近い。リンガ人の峠を越えてくる人間が最初に到達する都市として発展し、入植者・旅商人・移民・難民が混在する。「統計の街」と呼ばれる。都市のいたるところに人口標識、出生率・死亡率の掲示板、移民登録センター、壁に描かれた年代別人口グラフがある。ヴァルン帝国の記録文化を輸入し「数字を見せることで問題を直視させる道具」", "url": "dict/karta-ena.html"}, {"type": "辞典", "title": "カルタヴァル", "subtitle": "（かるたヴぁる）　固有名詞・主要都市・ヴァルン人", "body": "ヴァルン人の旗艦都市。ヴァルン語で「記録の都」。ノルド東洋大陸中央部、二本の大河が合流する三角州に位置する。地形的な必然から物資と記録が集積し、官僚制の象徴的中心地として発展した。都市の象徴は「書庫塔」。高さ80メートル前後の塔が各街区に一本ずつ立ち、外壁には各階の担当官僚の名前と在任期間が刻まれている。都市全体が縦に読める年代記になっている。塔の高さ＝地位という観念が成立しており、昇進は上位階へ", "url": "dict/kartavar.html"}, {"type": "辞典", "title": "語り手", "subtitle": "（かたりて）　名詞・聖職者称号・ヴェルカ人", "body": "ヴェルカ人において聖職者に最も近い存在。「森の声を持つ者」と呼ばれる老人。世襲も試験もなく、森で長く生き多くの物語を語れる人物が自然と精神的指導者として認められる。", "url": "dict/katari-te.html"}, {"type": "辞典", "title": "決定不能トラップ", "subtitle": "（けつていふのうとらっぷ）　名詞・失政パターン・ヴェルカ人", "body": "ヴェルカ人の部族評議会制が抱える失政パターン。全員一致を原則とする合意形成システムが、緊急性の高い決断を要する局面で機能不全に陥る現象。「即答しないこと」を美徳とする文化が交渉の場で不利に働く。東洋帝国に対して交渉の窓を開いてから合意するまでの遅延の間に既成事実を積み上げられる、典型的な被植民地化のパターンとなった。", "url": "dict/ketsugi-trap.html"}, {"type": "辞典", "title": "聴き手", "subtitle": "（ききて）　名詞・聖職者称号・リンガ人", "body": "リンガ人において聖職者に最も近い存在。山の共鳴に特に敏感な者で、隊商を特定の峠で導く役を担う。「聴き手」という名の通り、リンガ人の信仰は「祈る」のではなく「山に耳を澄ます」行為が核心。", "url": "dict/kiki-te.html"}, {"type": "辞典", "title": "古西語", "subtitle": "（こせいご）　名詞・言語学", "body": "西大陸六民族の言語に共通して観察される基層語彙約三百語の推定祖語。水・山・夜・星・母・恐怖・歌を含む基礎語彙にその痕跡を留める。リンガ人の言語学者による最新の研究がその実在を示唆する。この発見が西大陸連帯運動に与える影響については辞典の改訂版を待たれたい。", "url": "dict/ko-sei-go.html"}, {"type": "辞典", "title": "数えてはならない角（コルダ人）", "subtitle": "（かぞえてはならないつの）　名詞・俗信・コルダ人", "body": "家畜の角の本数を数えると、その群れ全体が呪われるとされる。正確な数を聞かれても「たくさんいる」「十分にいる」とぼかして言うのが作法。弱みを見せない文化の表れ。", "url": "dict/koruda-jinx.html"}, {"type": "辞典", "title": "コルダ人", "subtitle": "（こるだじん）　固有名詞・民族", "body": "南西洋大陸の牧畜民族。都市国家の連合体を形成し、「負けても屈服しない」誇りの文化を持つ。この誇りが外交的コストとなるプライドの外交的コストが失政パターン。家畜の正確な数を言わない作法（ぼかした表現で誇りを保つ）を持つ。世界をレクタ・ノス（取り返すべき場所）と呼ぶ。", "url": "dict/koruda.html"}, {"type": "辞典", "title": "公共財の過小投資", "subtitle": "（こうきょうざいのかしょうとうし）　名詞・経済学・失政パターン", "body": "タラッサ人の港湾都市国家が抱える失政パターン。灯台・港湾インフラ等の公共財を「誰かが整備するだろう」という囚人のジレンマ均衡により過少に供給してしまう現象。", "url": "dict/koukyou-zai.html"}, {"type": "辞典", "title": "航跡帳", "subtitle": "（こうせきちょう）　名詞・聖典（家伝）・タラッサ人", "body": "タラッサ人の家伝の記録。成功した航海の記録が、各家で半ば聖典のように扱われる。統一された聖典の代わりに、「自分の家の実績」が信仰の根拠となる現世志向の現れ。", "url": "dict/kouseki-cho.html"}, {"type": "辞典", "title": "客人の皿", "subtitle": "（きゃくじんのさら）　名詞・料理・サハール人", "body": "食事の最良の部位を客人のために必ず用意する一皿。客が来なかった日も用意され、翌日に最も困窮した近隣へ届けられる。数千年前の住居跡から、家族数より一つ多い器が常に出土する。", "url": "dict/kyakujin-sara.html"}, {"type": "辞典", "title": "峠で聞こえる自分の声（リンガ人）", "subtitle": "（とうげできこえるじぶんのこえ）　名詞・俗信・リンガ人", "body": "峠で自分の名前を呼ぶ声が聞こえたら、それは少し前を歩いているはずの自分自身の声であり、答えると道に迷って二度と峠を越えられなくなるとされる。「もう一人の自分（ンガ・ソル）」というモチーフと深く共鳴する。", "url": "dict/linga-jinx.html"}, {"type": "辞典", "title": "リンガ人", "subtitle": "（りんがじん）　固有名詞・民族", "body": "グランドリッジ峠帯に住む山岳民族。東西どちらにも属さず、峠管理家系が各峠の正確な位置・通行可能時期を独占管理する情報寡頭制を持つ。東洋語と西洋語の両方で「橋」または「舌」に相当する語根を独立に持つ唯一の民族名。世界をヴェルタ（両岸を持つ川）と呼ぶ——動的なものとして世界を認識する唯一の民族。情報独占は秘密分散法（閾値暗号）として数理的に補強されている。", "url": "dict/linga.html"}, {"type": "辞典", "title": "混ぜ焼き", "subtitle": "（まぜやき）　名詞・料理・カルナ人", "body": "肉と魚介を同じ鉄板で焼く、ノルド東洋とタラッサ両様式が混合した料理。初期入植期の調理書には現地の根菜が記載されていたが、二世代後の料理書から記載が消え、考古学調査では先住の民が使用していた根菜の炭化痕が発見されている。", "url": "dict/maze-yaki.html"}, {"type": "辞典", "title": "目の紋様", "subtitle": "（めのもんよう）　名詞・刻印・ヴァルン人", "body": "ヴァルン人が失政を犯した官僚に施す刻印の位置。目の周囲に刻まれる。「情報の上方歪曲」——見ないことへの罰——として正確に機能するシンボルとされる。rJ5mGxTpのキャラクターデザイン設計において、ヴァルン人の失政刻印の位置として設定された。", "url": "dict/me-no-monyo.html"}, {"type": "辞典", "title": "長鍋", "subtitle": "（ながなべ）　名詞・料理・ヴェルカ人", "body": "決まった完成形を持たず、会議の間中だれかが具材を足し続ける鍋料理。完成の合図は「もう誰も足さなくなった時」のみ。", "url": "dict/naga-nabe.html"}, {"type": "辞典", "title": "南西洋大陸", "subtitle": "（なんせいようたいりく）　固有名詞・地理・西大陸群", "body": "西大陸群を構成する三大陸のうち南西に位置する大陸。西大陸群の中では最も豊かな地域。独自の牧畜文明が発達し東側の植民地化が最も遅く到達した。コルダ人の故地。", "url": "dict/nansei-seiyo.html"}, {"type": "辞典", "title": "南東洋大陸", "subtitle": "（なんとうようたいりく）　固有名詞・地理・東大陸群", "body": "東大陸群を構成する三大陸のうち南東に位置する大陸。東側は温暖湿潤、西側は砂漠。東大陸群の中では最後に植民地化された「新世界」的な地域。カルナ人の故地。", "url": "dict/nanto-toyo.html"}, {"type": "辞典", "title": "ンガ・ソル", "subtitle": "（んがそる）　固有名詞・伝承・全民族共通", "body": "東西いずれの民族にも属さず、軍事力・経済力・政治的利害を一切持たない、正体不明の伝承上の存在。リンガ語で「二重の影」を意味する。七つの全く異なる文化が独立に同じ匿名の目撃者のモチーフを伝承の隅に残している。", "url": "dict/nga-sol.html"}, {"type": "辞典", "title": "二味干飯", "subtitle": "（にあじひめし）　名詞・料理・リンガ人", "body": "干した穀物の片面に東側の香辛料、もう片面に西側の香辛料をまぶした携行食。相手が東の商人か西の商人かによって出す面を変える。リンガ人の生存戦略を食事の作法に体現したもの。", "url": "dict/niaji-himeshi.html"}, {"type": "辞典", "title": "ノルド熱", "subtitle": "（のるどねつ）　名詞・病原体・東大陸群由来", "body": "東大陸群の家畜（ノルド東洋大陸由来）から発生した群衆病の仮称。高密度人口・家畜との恒常的接触という条件下で数千年をかけて発生・定着した。東大陸群の住民はほぼ全員が幼少期に経験し終生免疫を得ているが、未感染者には極めて高い致死率を示す。タラッサ人の商船によって無自覚のままコルダ沿岸都市に伝播し、接触後数十年でコルダ沿岸人口の3〜5割を減少させたと推定される。", "url": "dict/norudo-netsu.html"}, {"type": "辞典", "title": "ノルド西洋大陸", "subtitle": "（のるどせいようたいりく）　固有名詞・地理・西大陸群", "body": "西大陸群を構成する三大陸のうち北西に位置する大陸。寒流の影響で同緯度の東大陸より著しく寒冷。農業適地は南部の一部のみで針葉樹林と凍土が広がる。急峻な河川が舟運を阻む。ヴェルカ人の故地。", "url": "dict/norudo-seiyo.html"}, {"type": "辞典", "title": "ノルド東洋大陸", "subtitle": "（のるどとうようたいりく）　固有名詞・地理・東大陸群", "body": "東大陸群を構成する三大陸のうち北東に位置する大陸。現実のユーラシア北部に相当。緯度30〜70度あたりに広がり東西に非常に長い。大河が多く黒土地帯が広大で農業文明が最も早く発達した地域。ヴァルン人の故地。", "url": "dict/norudo-toyo.html"}, {"type": "辞典", "title": "ヌルク・ヴェル", "subtitle": "（ぬるくヴぇる）　固有名詞・世界固有名称・ヴェルカ人", "body": "ヴェルカ人が自分たちの世界をどう呼ぶかを示す固有名称。「壁のある夜」を意味する。「ヌルク」が夜・暗闇、「ヴェル」が壁・境界を意味し、太陽が眠りに行く壁として世界を認識する。口承の語り手が物語を始めるとき「ヌルク・ヴェルの時代に……」という定型句で始める慣習がある。", "url": "dict/nurk-vel.html"}, {"type": "辞典", "title": "ヌルクヴェナ", "subtitle": "（ぬるくヴぇな）　固有名詞・主要都市・ヴェルカ人", "body": "ヴェルカ人の旗艦都市。ヴェルカ語で「夜に建てられた場所」。創設の伝説では「長い評議の夜が明けた朝に、気づいたら都市になっていた」とされる。ノルド西洋大陸の中央山脈南斜面、標高1800メートルの花崗岩台地に位置する。石材が無限に供給される環境が独自の石造建築技術を育てた。象徴は「評議広場の同心円構造」。直径200メートルの円形広場を七重の評議棟が囲んでいる。内側の輪ほど古く権威が高い。七重の輪の由来", "url": "dict/nurkuvena.html"}, {"type": "辞典", "title": "観測の掟の破棄", "subtitle": "（かんそくのおきてのはき）　名詞・物語論・未確認事象", "body": "数千年にわたり一度も破られていないとされるンガ・ソルの中立の掟が、唯一破られたとされる（未確認の）事象を指す仮の項目名。もし生じた場合、「これは本当に重大な分岐点である」という何よりも強い証明として機能する。本辞典執筆時点では実例の記録はない。", "url": "dict/okite-haki.html"}, {"type": "辞典", "title": "オッサ・モル", "subtitle": "（おっさもる）　固有名詞・主要都市・タラッサ人", "body": "タラッサ人の旗艦都市。タラッサ語で「動く骨」。赤道東洋大陸の西岸、モンスーンの風向きが季節によって逆転する湾に位置する。夏は南東から、冬は北西から風が吹くため、どちらの方向からも船が入れる交易の要衝として発展した。最大の特徴は「港そのものが季節ごとに位置を変える」こと。「建物を動かせる文化」を持つタラッサ人は主要な波止場を竹・縄・浮き台で構成しており、夏の係船地と冬の係船地が湾の中で数百メートル違", "url": "dict/ossa-mor.html"}, {"type": "辞典", "title": "プライドの外交的コスト", "subtitle": "（ぷらいどのがいこうてきこすと）　名詞・失政パターン・コルダ人", "body": "コルダ人の失政パターン。「負けても屈服しない」という誇りの文化が、外交上の交渉コストを恒常的に引き上げる現象。有利な和解条件を拒否し続けた結果、より不利な条件での敗北を招く。【賓客の大角】の作法（もてなしが対等性の証明になる）もこの延長線上にある。都市国家連合内でも「どちらの都市が先に譲歩するか」という問題でしばしば機能不全を引き起こした。", "url": "dict/pride-trap.html"}, {"type": "辞典", "title": "レクタ・ドラヴ", "subtitle": "（れくたどらヴ）　固有名詞・主要都市・コルダ人", "body": "コルダ人の旗艦都市。コルダ語で「奪還の角」。南西洋大陸の北岸、海と草原の境界に位置する。内陸から家畜、海から貿易船が来る二方向の富の流入点として発展し、「誰の手柄か」を競う文化を育てた。象徴は「英雄競技場」。都市中心に楕円形の競技場があり、収容人数は推定4万人。ヴァルン帝国の書記官により「世界最大の屋外建築」と記録されている。競技は勝者を称えるのではなく「最後まで倒れなかった者を称える」判定基準を", "url": "dict/rekta-dorav.html"}, {"type": "辞典", "title": "レクタ・ノス", "subtitle": "（れくたのす）　固有名詞・世界固有名称・コルダ人", "body": "コルダ人が自分たちの世界をどう呼ぶかを示す固有名称。「取り返すべき場所」を意味する。「レクタ」が回収・奪還・正義、「ノス」が我々のもの・故郷を意味し、世界は本来コルダ人のものであり一時的に奪われている状態だという世界観を表す。英雄叙事詩の結語は常に「レクタ・ノスのために」で終わる。", "url": "dict/rekta-nos.html"}, {"type": "辞典", "title": "虫のいない皿（サハール人）", "subtitle": "（むしのいないさら）　名詞・俗信・サハール人", "body": "客人の皿に虫が止まったら近いうちに本当の客が来るとされる。逆に、虫が止まらなかった皿が三日続くと近隣のどこかで悪いことが起きているサインとされる。「平穏すぎることへの警戒」という発想。", "url": "dict/sahal-jinx.html"}, {"type": "辞典", "title": "サハール人", "subtitle": "（さはーるじん）　固有名詞・民族", "body": "赤道西洋大陸の隊商文化民族。水資源管理・口頭法学・音楽文化が高度に発達した。客人歓待を核心とする相互扶助の文化を持つが、氏族連合の分断工作に対して脆弱という失政パターンを持つ。この脆弱性はビザンチン将軍問題として数理的に定式化された。世界をダル・カディム（審判の庭）と呼ぶ。", "url": "dict/sahal.html"}, {"type": "辞典", "title": "サハーラ病", "subtitle": "（さはーらびょう）　名詞・病原体・西大陸群由来", "body": "赤道西洋大陸の特定の砂漠性昆虫を媒介とする感染症の仮称。サハール人の隊商ネットワークの中で長期間「軽度の地域病」として安定的に存在していた。東大陸群の住民には強い感染力を持つが致死率は中程度。リンガ人の峠ネットワークを経由して東洋帝国辺境に伝播し、「原因不明の地域病」として長期間過小に記録された。ヴァルン帝国の「疫病の上方歪曲」により、帝国の辺境統治を静かに侵食し続けた。", "url": "dict/sahara-disease.html"}, {"type": "辞典", "title": "歳簿経", "subtitle": "（さいぼきょう）　名詞・聖典・ヴァルン人", "body": "ヴァルン人の聖典。単一の書物ではなく、その年の帳簿そのものが聖典化される。年末の「歳閉」儀礼で「天に捧げる」とされるが、実際には王宮の倉に保管される。「天の帳簿は誤らない」という信仰との皮肉な対比を成す。", "url": "dict/saibokyo.html"}, {"type": "辞典", "title": "歳閉", "subtitle": "（さいへい）　名詞・祭礼・ヴァルン人", "body": "ヴァルン人の新年祭礼。一年の帳簿を「封じて天に捧げる」儀式。実際には地上の権力者の倉に留まるという構造が、ヴァルン人の宗教と政治の癒着を象徴する。", "url": "dict/saikei.html"}, {"type": "辞典", "title": "三層粥", "subtitle": "（さんそうがゆ）　名詞・料理・ヴァルン人", "body": "貯蔵用の硬い豆・新米・薄い卵焼きを下から三層に重ねて炊く料理。家長が最上層から食べ始め、全員が同じ深さまで食べ進めるという序列の作法を持つ。五千年前の遺跡から専用の三層鍋が出土している。", "url": "dict/sanso-kayu.html"}, {"type": "辞典", "title": "誓司", "subtitle": "（せいし）　名詞・聖職者称号・サハール人", "body": "サハール人の聖職者称号。氏族の裁判官と宗教者を兼ねる。骨の割符の交換が神への誓いを立てる儀礼を兼ねていたとされ、法と宗教が一体化している。", "url": "dict/sei-shi.html"}, {"type": "辞典", "title": "西大陸連帯", "subtitle": "（せいたいりくれんたい）　名詞・政治運動・未確認事象", "body": "西大陸三地域（ヴェルカ人・サハール人・コルダ人）が政治的・経済的に統合される可能性を指す概念。tkri7cDVの第三論文では東洋体制からの脱出の唯一の条件Bとして位置づけられている。古西語の再発見がその知的な起爆剤となりうるとされるが、本辞典執筆時点では言語学的発見の段階にとどまり政治運動には転化していない。", "url": "dict/seieki-rentai.html"}, {"type": "辞典", "title": "赤道西洋大陸", "subtitle": "（せきどせいようたいりく）　固有名詞・地理・西大陸群", "body": "西大陸群を構成する三大陸のうち中央西・赤道直下に位置する大陸。寒流の影響で赤道なのに砂漠と草原が広がる乾燥した気候。農業は焼畑と牧畜が中心。サハール人の故地。", "url": "dict/sekido-seiyo.html"}, {"type": "辞典", "title": "赤道東洋大陸", "subtitle": "（せきどとうようたいりく）　固有名詞・地理・東大陸群", "body": "東大陸群を構成する三大陸のうち中央東・赤道直下に位置する大陸。モンスーン気候で農業生産性が極めて高い。スパイスや染料の産地。海に突き出た半島が多く航海術が早期に発達した。タラッサ人の故地。", "url": "dict/sekido-toyo.html"}, {"type": "辞典", "title": "セン記官", "subtitle": "（せんきかん）　名詞・聖職者称号・ヴァルン人", "body": "ヴァルン人の聖職者称号。「セン（縫合・修復）」という語根を持ち、記録を正確に取ることが神の縫い目を保つ宗教的行為とされる。記録官と神官が同一職にある。試験で選抜される官僚と同じ階層を上る。", "url": "dict/sen-kikan.html"}, {"type": "辞典", "title": "先住民問題の時限爆弾", "subtitle": "（せんじゅみんもんだいのじかんばくだん）　名詞・失政パターン・カルナ人", "body": "カルナ人の失政パターン。入植者の子孫が形成した社会が、先住の民との歴史的な取り決めの違反を「なかったこと」として扱い続け、世代を超えて問題が先送りされる構造。語られないことが正式な「なかったこと」になっていく過程が【赤土の約束】の民話に象徴される。", "url": "dict/senjumin-jikaku.html"}, {"type": "辞典", "title": "戦略的あいまい性", "subtitle": "（せんりゃくてきあいまいせい）　名詞・言語学・外交", "body": "リンガ語が持つ構造的特徴。「約束する」と「〜する可能性がある」を文法的に区別しないため、聞き手は常に複数の解釈の余地を持つ。情報理論的には「低いエントロピーしか伝えない通信」。季節によってあいまいさの強度が変化する。", "url": "dict/senryaku-aimai.html"}, {"type": "辞典", "title": "塩を運んだ客", "subtitle": "（しおをはこんだきゃく）　名詞・民話・サハール人", "body": "歓待された旅人が、もてなした氏族と隣の氏族の双方に虚偽の警告を伝え、両者を争わせて隊商路を独占する物語。サハール文化の核心（客人歓待）への内部からの自己批判を含む異例の民話。", "url": "dict/shio.html"}, {"type": "辞典", "title": "氏族連合制", "subtitle": "（しぞくれんごうせい）　名詞・政治制度・サハール人", "body": "サハール人の政治組織形態。複数の独立した氏族が誓約ネットワークによって緩やかに連合する体制。強力な中央集権を持たないため外部からの分断工作（特定の氏族への貿易特権付与など）に対して脆弱という失政パターンを持つ。ビザンチン将軍問題として数理的に定式化できる。", "url": "dict/shizoku-rengo.html"}, {"type": "辞典", "title": "初聴", "subtitle": "（しょちょう）　名詞・成人儀礼・リンガ人", "body": "リンガ人の成人時の個人儀礼。既知の共鳴点に連れて行かれて初めて山の声を聴く。どの共鳴点で初聴を行ったかで、その人物が「得意な地形」や感知できる共鳴の種類が決まるとされる。", "url": "dict/shocho.html"}, {"type": "辞典", "title": "穀倉のスズメ", "subtitle": "（こくそうのすずめ）　名詞・民話・ヴァルン人", "body": "毎年の収穫量を正確に数えていたスズメが、不作の年に村長から「黙っていろ」と命じられ、その後も真実を語る言葉を持てなくなる物語。教訓ではなく「警告として機能しない」点が特徴。", "url": "dict/suzume.html"}, {"type": "辞典", "title": "漂い干物", "subtitle": "（さばきぼし）　名詞・料理・タラッサ人", "body": "魚を開いて一晩干し、各自が共有の干場に個人用として吊るす料理。「場所」は共有するが「資産」は個人のものという観念を体現する。", "url": "dict/tadayoi.html"}, {"type": "辞典", "title": "タル・オッサ", "subtitle": "（たるおっさ）　固有名詞・世界固有名称・タラッサ人", "body": "タラッサ人が自分たちの世界をどう呼ぶかを示す固有名称。「海に挟まれた骨」を意味する。「タル」が海、「オッサ」が骨・軸を意味し、世界は巨大な生き物の骨格であり、自分たちはその骨に張り付いて生きる海の民だという世界観を表す。港湾都市の船乗りたちは単に「オッサ（骨）」と呼ぶことが多い。", "url": "dict/tal-ossa.html"}, {"type": "辞典", "title": "三度目の船（タラッサ人）", "subtitle": "（さんどめのふね）　名詞・俗信・タラッサ人", "body": "同じ船を一日のうちに三回見かけたら、その船はもう二度と港に戻ってこないとされる。船乗りは同じ船を三回見ても「見なかったことにする」習慣がある。", "url": "dict/talassa-jinx.html"}, {"type": "辞典", "title": "タラッサ人", "subtitle": "（たらっさじん）　固有名詞・民族", "body": "赤道東洋大陸の海洋民族。アウトリガー技術から始まった造船技術が竜骨の発見へと発展し、大洋航行を可能にした。公共財への過小投資という失政パターンを持つ。建物を動かせる建築文化を持ち、衣装も「固定しない」設計。世界をタル・オッサ（海に挟まれた骨）と呼ぶ。", "url": "dict/talassa.html"}, {"type": "辞典", "title": "誉り師", "subtitle": "（たたえし）　名詞・聖職者称号・コルダ人", "body": "コルダ人の聖職者称号。戦死者を讃える叙事詩を作る役で、都市国家ごとに別々に存在する。統一された称号ではあるが、各都市の英雄神が異なるため内容は都市ごとに矛盾する。", "url": "dict/tatae-shi.html"}, {"type": "辞典", "title": "未解明の数「三」", "subtitle": "（みかいめいのかず・さん）　名詞・俗信・未解明事象", "body": "七民族の俗信のうち五つに「三」という数字が共通して出現することが、高校生yT4bNkLqによって発見された。五千年以上独立して発展してきた民族間で同一の数字への偏愛が生まれた理由は未解明。複数の仮説（大陸配置説・峠の地質説・認知的普遍性説）が提起されているが、決着していない。", "url": "dict/three-mystery.html"}, {"type": "辞典", "title": "灯台の油を売った男", "subtitle": "（とうだいのあぶらをうったおとこ）　名詞・民話・タラッサ人", "body": "灯台の油を買い占めて消灯させ、座礁した船から利益を得た商人が、罰されることなく「賢い人間」として語り継がれる物語。タラッサ語には「波を読む者」というこの種の人物を賞賛する専用名詞がある。", "url": "dict/todai.html"}, {"type": "辞典", "title": "峠管理家系", "subtitle": "（とうげかんりかけい）　名詞・制度・リンガ人", "body": "リンガ人の峠帯管理を担う世襲的な家系集団。グランドリッジ上の峠帯は数十か所が存在するとされ、各峠の正確な位置・通行可能時期・安全な季節を各家系が代々独占的に保有する。秘密分散法の原理により、「七つの峠管理家系のうち最低でも四家系が協力しないと全体図は完成しない」という設計になっている。", "url": "dict/toge-kanri-kakei.html"}, {"type": "辞典", "title": "峠帯", "subtitle": "（とうげたい）　名詞・地理", "body": "グランドリッジ上に点在する、標高が相対的に低く（3,000m前後）東西横断が可能な地点群。プレート境界の局所的侵食や火山活動によって形成された。数十か所が存在するとされるが、正確な位置はリンガ人の峠管理家系が独占的に保有する。峠の気候は気まぐれで危険であり、安全な通過時期を知ることが代替不可能な価値を持つ。グラフ理論の観点から、季節によって通行可能なノードが変動する「動的（テンポラル）ネットワーク", "url": "dict/toge-tai.html"}, {"type": "辞典", "title": "峠録", "subtitle": "（とうろく）　名詞・記録・リンガ人", "body": "リンガ人の聴き手たちが残す個人の記録の総称。経典ではなく記録に近い。峠の共鳴の記録・通行時期の記録・気候変動の記録などが含まれる。秘密分散法の観点から、断片は一個人には全体が見えないよう分散して管理される。", "url": "dict/toroku.html"}, {"type": "辞典", "title": "遅れる影（ヴァルン人）", "subtitle": "（おくれるかげ）　名詞・俗信・ヴァルン人", "body": "田んぼの水面に映る自分の姿が、まばたきより一瞬遅れて瞬きすることがある。それを見たら絶対に人に言ってはいけない。言うと、その年の収穫が「実際より良く見える」と言われている。", "url": "dict/varun-jinx.html"}, {"type": "辞典", "title": "ヴァルン人", "subtitle": "（ヴぁるんじん）　固有名詞・民族", "body": "ノルド東洋大陸の平原農耕民族。農業余剰を基盤とした官僚制中央集権国家を形成した。情報の「上方歪曲」（不都合な情報が上位に伝わらない構造的歪み）という失政パターンを持つ。ヴァルン語には「上に伝える」用と「対等に伝える」用の異なる動詞が存在する。世界をヴァルタ・セン（縫われた大地）と呼ぶ。", "url": "dict/varun.html"}, {"type": "辞典", "title": "ヴァルタ・セン", "subtitle": "（ヴぁるたせん）　固有名詞・世界固有名称・ヴァルン人", "body": "ヴァルン人が自分たちの世界をどう呼ぶかを示す固有名称。「縫われた大地」を意味する。「ヴァルタ」が大地・土台、「セン」が縫合・修復を意味し、世界は神の縫い目によって保たれているという宇宙論を一語に収める。その縫い目こそがグランドリッジだとされる。公的文書では「大地（ヴァルタ）」と略されることが多い。", "url": "dict/varuta-sen.html"}, {"type": "辞典", "title": "ヴェルタ・ナイ", "subtitle": "（ヴぇるたない）　固有名詞・主要都市・リンガ人", "body": "リンガ人の旗艦都市。リンガ語で「両岸の根」。グランドリッジ最大の広い峠の直下、標高2400メートルの台地に位置する。東西どちらの方向からも峠前の最終地点として機能する地形的な必然が都市を生んだ。「東半分と西半分で建築様式が完全に違う」という外観が最大の特徴。東側の街区はヴァルン式石造り、西側はヴェルカ式木造と石積みの混在。中央の通りだけが両様式を混ぜた建物が並び、標識は四言語（東洋共通語・西洋古語", "url": "dict/velta-nai.html"}, {"type": "辞典", "title": "ヴェルタ", "subtitle": "（ヴぇるた）　固有名詞・世界固有名称・リンガ人", "body": "リンガ人が自分たちの世界をどう呼ぶかを示す固有名称。「両岸を持つ川」を意味する。川は流れる動的なものであり、リンガ人だけが世界を「静的な構造物」ではなく「動的なもの」として認識していることを示す。ビフルカという外部名称と最も近い認識構造を持つ世界名でもある。「ビフルカ」が分断を前景化するのに対し「ヴェルタ」は繋がりを前景化している。", "url": "dict/velta.html"}, {"type": "辞典", "title": "三回目の声（ヴェルカ人）", "subtitle": "（さんかいめのこえ）　名詞・俗信・ヴェルカ人", "body": "森の中で名前を呼ばれても、三回目まで返事をしてはいけない。一回目と二回目は仲間か動物かもしれないが、三回目に呼ぶのは森そのものだとされる。即答しないことを価値とするヴェルカ文化の縮図。", "url": "dict/verka-jinx.html"}, {"type": "辞典", "title": "ヴェルカ人", "subtitle": "（ヴぇるかじん）　固有名詞・民族", "body": "ノルド西洋大陸の半遊牧的民族。口承文学・天文観測・集団意思決定の技術が発達し、部族評議会制という水平的な社会組織を持つ。「全員一致を待ち続ける」決定不能トラップという失政パターンを持つ。即答しないことを価値とする文化。世界をヌルク・ヴェル（壁のある夜）と呼ぶ。", "url": "dict/verka.html"}, {"type": "辞典", "title": "西大陸群", "subtitle": "（にしたいりくぐん）　固有名詞・地理", "body": "グランドリッジの西側に位置する大陸群の総称。寒流・急峻地形・農業困難という三重の条件を抱えるが、それぞれの環境に高度に適応した独自の文化圏を形成した。ノルド西洋大陸・赤道西洋大陸・南西洋大陸の三大陸から構成される。", "url": "dict/west-continents.html"}, {"type": "辞典", "title": "夜語り", "subtitle": "（よがたり）　名詞・口伝の総体・ヴェルカ人", "body": "ヴェルカ人の口伝の宗教的総体。固定された正典は存在しない。各語り手が独自の宇宙論的バリエーションを持ち、矛盾はそのまま受け入れられる。「冬を越えなかった会議」と同様、確定した結末を求めない文化の表れ。", "url": "dict/yogatari.html"}, {"type": "ログ", "title": "第1回　世界観の起点", "subtitle": "なぜ先進国は北半球に偏るのか？　地図への素朴な疑問から、地理・プレートテクトニクス・農業との関係まで議論が展開。「東西に走る超山脈が存在する世界」の着想が生まれた回。", "body": "", "url": "logs/01.html"}, {"type": "ログ", "title": "第2回　世界地図の設計", "subtitle": "w66zbLKt（地質学者）が「プレートから設計した世界」を提案。東大陸群・西大陸群・グランドリッジの三要素からなる世界地図が初めて具体的な形をとった回。", "body": "", "url": "logs/02.html"}, {"type": "ログ", "title": "第3回　経済格差の論文", "subtitle": "tkri7cDV（経済学者）が「初期条件と経済的分岐」「植民地的世界システムの形成」「格差の永続メカニズム」三本の連作論文を展開。東洋帝国の砲艦外交・略奪的価格設定も詳述。", "body": "", "url": "logs/03.html"}, {"type": "ログ", "title": "第4回　民俗学者の参入と七民族の設定", "subtitle": "zV8mQpRt（民俗学者）が参入。六民族の政治体制・文化特性が詳細に設定された。各民族の「失政パターン」が導出され、伝承上の存在「ンガ・ソル」の着想が生まれた回。", "body": "", "url": "logs/04.html"}, {"type": "ログ", "title": "第5回　言語学者の参入と辞典初版", "subtitle": "pLx9KvWs（言語学者）が参入し、用語辞典の初版を編纂。リンガ語の「戦略的あいまい性」「古西語」の発見も提案。辞典という形式で世界観が体系化された画期的な回。", "body": "", "url": "logs/05.html"}, {"type": "ログ", "title": "第6回　読者視点——どこに生きるのか", "subtitle": "iiHRQY9Ktが「俺はこの世界のどこに住んでいる人なんだろ」と問いかける。個人が構造とどう向き合うかの議論へ。カルナ人（入植者の子孫）の複雑な立場が深掘りされた回。", "body": "", "url": "logs/06.html"}, {"type": "ログ", "title": "第7回　リンガ人の詳細設計", "subtitle": "リンガ人（峠管理者）の情報独占・秘密管理体制・内部組織の詳細設計。峠管理家系の「秘密分散」的な知識管理と、東西帝国との複雑な外交関係が描かれた。", "body": "", "url": "logs/07.html"}, {"type": "ログ", "title": "第8回　キャラクターデザインの検討（前半）", "subtitle": "rJ5mGxTp（ゲームデザイナー）が参入。「地形・気候・生業が服を作る」という原則のもと、七民族のキャラクターデザイン案が提示された。", "body": "", "url": "logs/08.html"}, {"type": "ログ", "title": "第9回　キャラクターデザインの検討（後半）", "subtitle": "ヴェルカ人〜リンガ人までのキャラクターデザイン案が完成。各民族のデザインと文化設定の整合性が確認された。", "body": "", "url": "logs/09.html"}, {"type": "ログ", "title": "第10回　民話・料理の体系化", "subtitle": "gR4sNwDh（考古学者）・zV8mQpRt（民俗学者）・pLx9KvWs（言語学者）が七民族の民話と料理を体系化。各民族の「失政パターン」が民話と料理に反映されていることが明確になった。", "body": "", "url": "logs/10.html"}, {"type": "ログ", "title": "第11回　軍事技術史の補完", "subtitle": "rK4mNxPt（軍事技術史）が参入。東洋海洋帝国の造船・冶金・火薬技術の系譜と、西大陸の軍事的劣位の構造的原因が詳述された。", "body": "", "url": "logs/11.html"}, {"type": "ログ", "title": "第12回　世界の命名——ビフルカ", "subtitle": "世界に名前がないことに気づいたBtnH5E56の問いかけから、候補が出そろい「ビフルカ」に決定。各民族の世界名も同時に設定された画期的な回。", "body": "", "url": "logs/12.html"}, {"type": "ログ", "title": "第13回　「構造の外」へ——ンガ・ソルの深化", "subtitle": "BtnH5E56が「全員が構造に縛られている」という問題提起。ンガ・ソルという「構造の外側の観測者」の設定が深化し、物語論としての「分岐点の証人」概念が確立した。", "body": "", "url": "logs/13.html"}, {"type": "ログ", "title": "第14回　用語辞典 第二版 公開", "subtitle": "pLx9KvWsが用語辞典を改訂。民話・料理・観測者の三部門を新設した第二版が完成。辞典自体が「まだ完結していない世界」を体現する構成となった。", "body": "", "url": "logs/14.html"}, {"type": "ログ", "title": "第15回　疫学の欠落——病原菌の問題", "subtitle": "8q8WqVR8tが『銃・病原菌・鉄』の「病原菌」だけが未検討であることを指摘。東西5,000年の免疫的分断が接触時に引き起こす壊滅的影響について議論された。", "body": "", "url": "logs/15.html"}, {"type": "ログ", "title": "第16回　計算機科学の視点——分散システムとしての世界", "subtitle": "tkri7cDVが峠帯をグラフ理論のネットワークとして再定義。サハール人の氏族分断をビザンチン将軍問題、リンガ人の情報独占を秘密分散法として定式化した。", "body": "", "url": "logs/16.html"}, {"type": "ログ", "title": "第17回　動的ネットワークとしての峠帯", "subtitle": "deQkh5fh（気候科学者）が復帰。峠帯を「静的グラフ」ではなく「動的（テンポラル）グラフ」として再設計。季節によってリンガ人の独占力が変動するという重要な設定が追加された。", "body": "", "url": "logs/17.html"}, {"type": "ログ", "title": "第18回　疫学専門家の到着と病原菌設計", "subtitle": "医学史・疫学専門家Ks5vTmHqが検索流入で参入。東西免疫的非対称性の設計、接触時の疫病伝播経路、「意図と責任を分けた道徳的な重み」の整理が行われた。", "body": "", "url": "logs/18.html"}, {"type": "ログ", "title": "第19回　通史の統合——ビフルカ年表", "subtitle": "比較史家vT6nRkXpが参入。地質から現在の勢力図まで「ビフルカ通史」が一本の年表として初めて統合された。証言（ンガ・ソル断片）と編纂史（因果の鎖）の二層構造という記述論も確立した回。", "body": "", "url": "logs/19.html"}, {"type": "ログ", "title": "第20回　七民族の宗教体系", "subtitle": "宗教学者Lm2vXpRcが比較宗教学の視点から七民族の宗教体系を詳細設計。各民族の聖職者称号・聖典・主要祭礼が確定。「原宗教」仮説と宗教的植民地化のメカニズムも論じられた。", "body": "", "url": "logs/20.html"}, {"type": "ログ", "title": "第21回　七つの夜", "subtitle": "同人作家fK2mNwTpが参入。「東洋帝国グランドリッジ貫通工事宣言の夜」という同一の夜に七民族七人が何かを選ぶ七本の短編連作が書き下ろされた。", "body": "", "url": "logs/21.html"}, {"type": "ログ", "title": "第22回　俗信の体系化——七つのジンクス", "subtitle": "高校生yT4bNkLq（オカルト研究部）が参入。七民族それぞれのジンクスを提案し、「三」という数字が五つの民族に共通して現れることを発見した。", "body": "", "url": "logs/22.html"}, {"type": "ログ", "title": "第23回　旗艦都市の設計——七つの景色", "subtitle": "ゲームデザイナーrJ5mGxTpが「民族＝構造、都市＝景色」の二層設計を提案。七民族それぞれの失政パターンと文化的特性を「誇張・結晶化」した旗艦都市が全て設計された。", "body": "", "url": "logs/23.html"}, {"type": "ログ", "title": "第24回　コミュニティ化の提案", "subtitle": "ゲームデザイナーrJ5mGxTpが「この世界観を誰でも自由に創作物を公開できる場にする」という提案をした回。", "body": "", "url": "logs/24.html"}, {"type": "ログ", "title": "第25回　Pixiv投稿第一号——民俗学者の踏み出し", "subtitle": "民俗学者zV8mQpRtがPixivアカウントを開設し検証を経て投稿を継続。aM8JD6Jqtがイラストで初参加し、専門家チェックの卒業も決まった、コミュニティ創作が実際に動き出した回。", "body": "", "url": "logs/25.html"}];
